def solve(nums, k):
    def quickselect(start, end, k):
        pivot = nums[end]
        i = start
        for j in range(start, end):
            if nums[j] <= pivot:
                nums[i], nums[j] = nums[j], nums[i]
                i += 1
        nums[i], nums[end] = nums[end], nums[i]
        if i == k - 1:
            return nums[i]
        elif i < k - 1:
            return quickselect(i + 1, end, k)
        else:
            return quickselect(start, i - 1, k)

    return quickselect(0, len(nums) - 1, k)
