def solve(haystack, needle):
    len_h = len(haystack)
    len_n = len(needle)

    if len_n > len_h:
        return -1

    if len_n == 0:
        return 0

    for i in range(len_h - len_n + 1):
        if haystack[i:(i + len_n)] == needle:
        return i

    return -1
```

