def solve(haystack, needle):
    len_hay = len(haystack)
    len_nee = len(needle)

    if len_nee > len_hay:
        return -1

    def check_start(i):
        for j in range(len_nee):
            if haystack[i + j] != needle[j]:
                return False
        return True

    for i in range(len_hay - len_nee + 1):
        if check_start(i):
            return i
    return -1
