def solve(intervals):
    if not intervals:
        return 0

    # Sort intervals by end time
    intervals.sort(key=lambda x: x[1])

    removed = 0
    prev_end = -float('inf')

    # Iterate through sorted intervals
    for start, end in intervals:
        if prev_end > start:
            removed += 1
        else:
            prev_end = max(prev_end, end)

    return removed
```

