def solve(n, prerequisites):
    from collections import deque

    graph = [[] for _ in range(n)]
    in_degree = [0] * n

    for a, b in prerequisites:
        graph[b].append(a)
        in_degree[a] += 1

    q = deque()
    for i in range(n):
        if in_degree[i] == 0:
            q.append(i)

    result = []
    while q:
        node = q popleft()
        result.append(node)
        for neighbor in graph[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                q.append(neighbor)

    if len(result) != n:
        return []
    return result
```

